#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Создаём объект, передавая адрес и размеры экрана
LiquidCrystal_I2C lcd(0x38, 20, 4);

void setup() {
    // Инициализируем экран
    lcd.init();
    // Включаем подсветку
    lcd.backlight();

    // Ставим курсор и выводим текст
    lcd.setCursor(0, 0);
    lcd.print("Hello Amperka");

    lcd.setCursor(0, 1);
    lcd.print("Do It Yourself");

    lcd.setCursor(0, 2);
    lcd.print("LCD Screen 20x4");

    lcd.setCursor(0, 3);
    lcd.print("www.Amperka.ru");
}

